function scenarioDayTone(tempDelta:number,rainDelta:number,gustDelta:number){if(rainDelta>=1)return'wetter';if(rainDelta<=-1)return'trockener';if(tempDelta>=1.5)return'waermer';if(tempDelta<=-1.5)return'kuehler';if(gustDelta>=5)return'windiger';if(gustDelta<=-5)return'ruhiger';return'nahe'}
function scenarioDayDeltas(point:EnsembleScenarioCluster['points'][number],baseline:EnsembleScenarioCluster['points'][number]|undefined){if(!baseline)return[] as string[];const temp=((point.max+point.min)-(baseline.max+baseline.min))/2,rain=point.precipitation-baseline.precipitation,gust=Number.isFinite(point.gust)&&Number.isFinite(baseline.gust)?point.gust-baseline.gust:NaN,items:string[]=[];if(Math.abs(temp)>=.5)items.push(`Temperatur ${signedScenarioValue(temp,1,' K')}`);if(Math.abs(rain)>=.2)items.push(`Niederschlag ${signedScenarioValue(rain,1,' mm')}`);if(Number.isFinite(gust)&&Math.abs(gust)>=2)items.push(`Böen ${signedScenarioValue(gust,0,' kt')}`);return items}
function scenarioRoleLabel(index:number){return index===0?'wahrscheinlichster Verlauf':index===1?'erste Alternative':'zweite Alternative'}
function scenarioComparatorSummary(scenario:EnsembleScenarioCluster,baseline:EnsembleScenarioCluster|undefined){if(!baseline||scenario.id===baseline.id)return'Leitvariante als Referenz für die weiteren Szenarien.';const points=scenario.points.slice(0,5),basePoints=baseline.points.slice(0,5),tempDelta=points.reduce((sum,point,index)=>sum+(((point.max+point.min)-(basePoints[index]?.max+basePoints[index]?.min||0))/2),0)/Math.max(1,points.length),rainDelta=points.reduce((sum,point,index)=>sum+(point.precipitation-(basePoints[index]?.precipitation??0)),0),gustValues=points.map((point,index)=>Number.isFinite(point.gust)&&Number.isFinite(basePoints[index]?.gust)?Number(point.gust)-Number(basePoints[index]?.gust):NaN).filter(Number.isFinite),gustDelta=gustValues.length?gustValues.reduce((sum,value)=>sum+Number(value),0)/gustValues.length:NaN;const parts:string[]=[];if(Math.abs(tempDelta)>=.5)parts.push(tempDelta>0?`im Mittel rund ${formatDecimal(tempDelta,1,1)} K wärmer`:`im Mittel rund ${formatDecimal(Math.abs(tempDelta),1,1)} K kühler`);if(Math.abs(rainDelta)>=.5)parts.push(rainDelta>0?`${formatDecimal(rainDelta,1,1)} mm nasser`:`${formatDecimal(Math.abs(rainDelta),1,1)} mm trockener`);if(Number.isFinite(gustDelta)&&Math.abs(gustDelta)>=2)parts.push(gustDelta>0?`etwas windiger`:`etwas ruhiger`);return parts.length?`Gegenüber A ${parts.join(' · ')}.`:'In den ersten fünf Tagen nahe am Szenario A.'}
function EnsembleScenarioClusters({scenarios,open,onToggle}:{scenarios:EnsembleScenarioCluster[];open:boolean;onToggle:()=>void}){
 if(scenarios.length<2)return null;
 const visible=scenarios.slice(0,3),baseline=visible[0],displayPercentages=apportionScenarioPercentages(visible.map(scenario=>scenario.probability)),divergence=visible.find(item=>item.divergenceDate)?.divergenceDate,probabilitySummary=visible.map((_,index)=>`${String.fromCharCode(65+index)} ${displayPercentages[index]} %`).join(' · ');
 return <section className={`ensemble-scenarios${open?'':' collapsed'}`} aria-label="Ensemble-Szenariocluster"><header className="ensemble-advanced-header"><button type="button" className="ensemble-advanced-toggle" aria-expanded={open} onClick={onToggle}><span><small>Nur im erweiterten Modus</small><strong>Szenario-Cluster</strong><em>{probabilitySummary}</em></span><ChevronDown size={18}/></button><InfoHint label="Szenariocluster erklären"><strong>Ensemble-Szenariocluster</strong><p>MID gruppiert vollständige Ensembleverläufe nach Temperatur, zeitlicher Niederschlagsentwicklung und – soweit geliefert – Böen.</p><p>Jede Karte beschreibt einen vollständigen Verlauf. <b>A</b> ist die wahrscheinlichste Leitvariante; <b>B</b> und <b>C</b> sind plausible Alternativen. Die Prozentwerte zeigen den relativen Anteil der nach Modellfamilien gewichteten Ensemblemitglieder.</p><p>Ab Szenario B werden die wichtigsten Abweichungen gegenüber dem führenden Szenario A direkt am jeweiligen Tag ausgewiesen. Farbliche Akzente markieren vor allem nassere, trockenere, wärmere, kühlere oder windigere Varianten.</p><p>Die Anteile sind keine amtlichen Eintrittswahrscheinlichkeiten. Sie werden gemeinsam gerundet und ergeben deshalb stets exakt 100 %.</p></InfoHint></header>{open&&<div className="ensemble-advanced-body"><div className="ensemble-scenario-probability-overview" aria-label="Relative Wahrscheinlichkeit der Szenarien">{visible.map((scenario,index)=>{const letter=String.fromCharCode(65+index),percentage=displayPercentages[index];return <span key={`overview-${scenario.id}`} className={index===0?'leading':''}><header><b>{letter}</b><strong>{percentage} %</strong></header><small>{scenario.label}</small><i aria-hidden="true"><em style={{width:`${percentage}%`}}/></i></span>})}</div>{divergence?<p>Die Szenarien beginnen sich voraussichtlich ab <b>{formatDateOnly(divergence,{weekday:'long',day:'2-digit',month:'2-digit'})}</b> markant zu unterscheiden.</p>:<p>In den kommenden Tagen ist noch kein stabiler markanter Trennungszeitpunkt erkennbar.</p>}<div className="ensemble-scenario-cards">{visible.map((scenario,index)=>{const relevant=scenario.points.slice(0,5),minimum=Math.min(...relevant.map(point=>point.min)),maximum=Math.max(...relevant.map(point=>point.max)),rain=relevant.reduce((sum,point)=>sum+Math.max(0,point.precipitation),0),gusts=relevant.map(point=>point.gust).filter(Number.isFinite),gust=gusts.length?Math.max(...gusts):NaN,shares=scenario.modelShares??scenario.modelLabels.map((label,shareIndex)=>({id:`legacy-${shareIndex}`,label,memberCount:0,familyMemberCount:0,familyShare:NaN})),roleLabel=scenarioRoleLabel(index),comparisonText=scenarioComparatorSummary(scenario,baseline);return <article key={scenario.id} className={index===0?'leading':''}><header><b>{String.fromCharCode(65+index)}</b><span><strong>{scenario.label}</strong><small>{roleLabel} · {scenario.memberCount} Mitglieder · {scenario.modelLabels.length} {scenario.modelLabels.length===1?'Modellfamilie':'Modellfamilien'}</small></span><em title="Relativer Anteil der gewichteten Ensemblemitglieder; gemeinsam auf exakt 100 % gerundet">{displayPercentages[index]} %</em></header><div className="ensemble-scenario-probability-meter" aria-label={`Szenario ${String.fromCharCode(65+index)}: ${displayPercentages[index]} Prozent`}><i><em style={{width:`${displayPercentages[index]}%`}}/></i><small>{index===0?'führende Variante':`${index}. Alternative`}</small></div><p className="ensemble-scenario-explainer">{comparisonText}</p><div className="ensemble-scenario-metrics"><span><small>Regen in 5 Tagen</small><b>{formatDecimal(rain,1,1)} mm</b></span><span><small>Temperaturspanne · 5 Tage</small><b>{scenarioTemperatureRange(minimum,maximum)}</b></span><span><small>Böenspitze</small><b>{Number.isFinite(gust)?`${Math.round(gust)} kt`:'nicht verfügbar'}</b></span></div><div className="ensemble-scenario-days-label"><b>Sieben-Tage-Verlauf</b><small>Pro Tag: Temperatur · Niederschlag · Böen{index>0?' · wichtigste Abweichung zu A':''}</small></div><div className="ensemble-scenario-days">{scenario.points.slice(0,7).map((point,dayIndex)=>{const base=baseline.points[dayIndex],tempDelta=base?((point.max+point.min)-(base.max+base.min))/2:0,rainDelta=base?point.precipitation-base.precipitation:0,gustDelta=base&&Number.isFinite(point.gust)&&Number.isFinite(base.gust)?point.gust-base.gust:0,deltas=index>0?scenarioDayDeltas(point,base):[],tone=index>0?scenarioDayTone(tempDelta,rainDelta,gustDelta):'referenz';return <section key={point.date} className={`ensemble-scenario-day ${tone}`} title={`${formatDateOnly(point.date,{weekday:'long',day:'2-digit',month:'2-digit'})}: ${scenarioTemperatureRange(point.min,point.max)} · ${formatDecimal(point.precipitation,1,1)} mm${Number.isFinite(point.gust)?` · Böen ${Math.round(point.gust)} kt`:''}`}><header><b>{formatDateOnly(point.date,{weekday:'short'})}</b><small>{formatDateOnly(point.date,{day:'2-digit',month:'2-digit'})}</small></header><strong>{scenarioTemperatureRange(point.min,point.max)}</strong><span><small>Niederschlag</small><b>{formatDecimal(point.precipitation,1,1)} mm</b></span><span><small>Böenspitze</small><b>{Number.isFinite(point.gust)?`${Math.round(point.gust)} kt`:'–'}</b></span><div className="ensemble-scenario-deltas">{index===0?<em>Leitvariante A</em>:deltas.length?deltas.slice(0,3).map(item=><em key={item}>{item}</em>):<em>nahe an A</em>}</div></section>})}</div><div className="ensemble-scenario-models" aria-label="Verteilung der Modellfamilien in diesem Szenario"><div className="ensemble-scenario-models-title"><b>Welche Modellfamilien tragen dieses Szenario?</b><small>Eine Modellfamilie kann in mehreren Szenarien erscheinen, wenn ihre Mitglieder unterschiedliche Lösungen berechnen.</small></div>{shares.slice(0,6).map(share=><span key={share.id}><b>{share.label}</b><small>{Number.isFinite(share.familyShare)&&share.familyMemberCount>0?`${share.memberCount} von ${share.familyMemberCount} Mitgliedern · ${Math.round(share.familyShare)} % der Modellfamilie`:'im Szenario vertreten'}</small></span>)}</div></article>})}</div></div>}</section>
}
function safeFilePart(value:string){return value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'').toLowerCase()||'standort'}
function ensembleRunSource(runs:ModelRunMeta[]){return runs.length?runs.map(run=>`${run.label}: Init ${formatModelRunTime(run.initialisationTime)} · verfügbar ${formatAvailabilityTime(run.availabilityTime)}`).join(' | '):'Modellstände derzeit nicht verfügbar'}
function downloadBlob(blob:Blob,filename:string){const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;link.rel='noopener';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),2000)}
